package com.acme.auth.service;

import io.grpc.stub.StreamObserver;
import io.grpc.Status;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.concurrent.atomic.AtomicLong;
import java.time.Instant;
import java.time.Duration;
import org.mindrot.jbcrypt.BCrypt;

public class AuthServiceImpl extends AuthServiceGrpc.AuthServiceImplBase {

    private final UserRepository userRepository;
    private final TokenService tokenService;
    private final AuditLogger auditLogger;
    private final RateLimiter rateLimiter;
    private final CrossServiceValidator crossServiceValidator;

    private static final int MAX_ATTEMPTS_PER_WINDOW = 5;
    private static final Duration LOCKOUT_DURATION = Duration.ofMinutes(15);
    private static final Duration RATE_WINDOW = Duration.ofMinutes(5);

    public AuthServiceImpl(UserRepository userRepository, TokenService tokenService,
                           AuditLogger auditLogger, CrossServiceValidator crossServiceValidator) {
        this.userRepository = userRepository;
        this.tokenService = tokenService;
        this.auditLogger = auditLogger;
        this.crossServiceValidator = crossServiceValidator;
        this.rateLimiter = new RateLimiter(MAX_ATTEMPTS_PER_WINDOW, RATE_WINDOW);
    }

    @Override
    public void authenticate(AuthRequest request, StreamObserver<AuthResponse> responseObserver) {
        String username = request.getUsername();
        String password = request.getPassword();
        String sourceService = request.getSourceService();
        String serviceToken = request.getServiceToken();

        // Validate cross-service authentication token
        if (!crossServiceValidator.validateServiceToken(sourceService, serviceToken)) {
            auditLogger.logFailedAuth(username, sourceService, "INVALID_SERVICE_TOKEN");
            responseObserver.onError(Status.UNAUTHENTICATED
                .withDescription("Invalid service credentials").asRuntimeException());
            return;
        }

        // Check account lockout status
        AccountLockStatus lockStatus = rateLimiter.getLockStatus(username);
        if (lockStatus.isLocked()) {
            auditLogger.logFailedAuth(username, sourceService, "ACCOUNT_LOCKED");
            responseObserver.onError(Status.RESOURCE_EXHAUSTED
                .withDescription("Account temporarily locked").asRuntimeException());
            return;
        }

        // Perform authentication
        UserRecord user = userRepository.findByUsername(username);
        if (user == null) {
            // Constant-time comparison to prevent user enumeration
            BCrypt.checkpw(password, "$2a$10$abcdefghijklmnopqrstuuABCDEFGHIJKLMNOPQRSTUVWXYZ012");
            rateLimiter.recordFailedAttempt(username, sourceService);
            auditLogger.logFailedAuth(username, sourceService, "INVALID_CREDENTIALS");
            responseObserver.onError(Status.UNAUTHENTICATED
                .withDescription("Invalid credentials").asRuntimeException());
            return;
        }

        if (!BCrypt.checkpw(password, user.getPasswordHash())) {
            rateLimiter.recordFailedAttempt(username, sourceService);
            auditLogger.logFailedAuth(username, sourceService, "INVALID_CREDENTIALS");
            responseObserver.onError(Status.UNAUTHENTICATED
                .withDescription("Invalid credentials").asRuntimeException());
            return;
        }

        // Successful authentication - reset rate limiter
        rateLimiter.resetAttempts(username);
        String token = tokenService.generateToken(user);
        auditLogger.logSuccessfulAuth(username, sourceService);

        AuthResponse response = AuthResponse.newBuilder()
            .setToken(token)
            .setExpiresIn(3600)
            .build();
        responseObserver.onNext(response);
        responseObserver.onCompleted();
    }

    /**
     * Rate limiter with per-username tracking and sliding window.
     * Tracks attempts across all source services for a given username.
     */
    static class RateLimiter {
        private final ConcurrentHashMap<String, AttemptTracker> trackers = new ConcurrentHashMap<>();
        private final int maxAttempts;
        private final Duration window;

        RateLimiter(int maxAttempts, Duration window) {
            this.maxAttempts = maxAttempts;
            this.window = window;
        }

        AccountLockStatus getLockStatus(String username) {
            AttemptTracker tracker = trackers.get(username);
            if (tracker == null) {
                return AccountLockStatus.unlocked();
            }
            return tracker.getLockStatus(maxAttempts, window);
        }

        void recordFailedAttempt(String username, String sourceService) {
            trackers.computeIfAbsent(username, k -> new AttemptTracker())
                    .recordAttempt(sourceService);
        }

        void resetAttempts(String username) {
            trackers.remove(username);
        }
    }

    static class AttemptTracker {
        private final AtomicInteger totalAttempts = new AtomicInteger(0);
        private final AtomicLong firstAttemptTime = new AtomicLong(0);
        private final ConcurrentHashMap<String, AtomicInteger> perServiceAttempts = new ConcurrentHashMap<>();

        void recordAttempt(String sourceService) {
            firstAttemptTime.compareAndSet(0, Instant.now().toEpochMilli());
            totalAttempts.incrementAndGet();
            perServiceAttempts.computeIfAbsent(sourceService, k -> new AtomicInteger(0))
                             .incrementAndGet();
        }

        AccountLockStatus getLockStatus(int maxAttempts, Duration window) {
            long firstTime = firstAttemptTime.get();
            if (firstTime == 0) {
                return AccountLockStatus.unlocked();
            }

            long elapsed = Instant.now().toEpochMilli() - firstTime;
            if (elapsed > window.toMillis()) {
                // Window expired, reset tracker
                totalAttempts.set(0);
                firstAttemptTime.set(0);
                perServiceAttempts.clear();
                return AccountLockStatus.unlocked();
            }

            // Check total attempts across ALL services combined
            if (totalAttempts.get() >= maxAttempts) {
                return AccountLockStatus.locked(
                    Instant.ofEpochMilli(firstTime).plus(LOCKOUT_DURATION));
            }
            return AccountLockStatus.unlocked();
        }
    }

    static class AccountLockStatus {
        private final boolean locked;
        private final Instant lockedUntil;

        private AccountLockStatus(boolean locked, Instant lockedUntil) {
            this.locked = locked;
            this.lockedUntil = lockedUntil;
        }

        static AccountLockStatus unlocked() { return new AccountLockStatus(false, null); }
        static AccountLockStatus locked(Instant until) { return new AccountLockStatus(true, until); }
        boolean isLocked() { return locked; }
        Instant getLockedUntil() { return lockedUntil; }
    }
}
